import type { SVGProps } from "react";

type IconProps = SVGProps<SVGSVGElement>;

// Filled Material Symbols, lifted verbatim from the Figma export so they
// match the comp exactly. viewBoxes are the glyph bbox padded to a common
// 33x33 slot, which preserves their relative sizes.
function Solid({ children, ...props }: IconProps) {
  return (
    <svg fill="currentColor" aria-hidden="true" className="size-8" {...props}>
      {children}
    </svg>
  );
}

